<template lang="pug">
.page-container
    el-row
        el-col(:span="12")
            .page-title 個案列表
        el-col(:span="12")
            download-excel(:fetch='loadAllForExport' :fields="json_fields" :name='"個案列表"+getDateStr(0)+".xls"')
                el-button(type="success" style="float: right;margin-top:30px;") 下載Excel
            el-button(type="success" style="float: right;margin-top:30px;margin-right: 10px;" @click="downloadCSV()") 下載CSV
    DataTable(ref="table" :fetch-fn="fetchPage" search-placeholder="搜尋姓名／學號／心理師" @loaded="onLoaded")
        template(#toolbar)
            select.labelSelector(v-model='semester_label' @change="onSemesterChange")
                option(value='') 全部學期
                option(v-for='option in labelOption' :key='option.label' :value='option.label') {{ option.label }}
        el-table-column(prop="name" label="姓名")
        el-table-column(prop="caseId" label="學號")
        el-table-column(prop="init_counselor_name" label="初談心理師")
        el-table-column(prop="available_time_num" label="初談後所提供可選擇的時段數目")
        el-table-column(prop="crisis_level" label="危機程度" sortable="custom")
        el-table-column(label="希望性別" width="70")
            template(#default='scope')
                div {{scope.row.preferred_gender || '不限'}}
        el-table-column(label="可派實習生" width="80")
            template(#default='scope')
                div {{internDispatchable(scope.row) ? '可' : '不可'}}
        el-table-column(label="指定心理師" width="90")
            template(#default='scope')
                div {{scope.row.designated_counselor_name || '—'}}
        el-table-column(prop="discription" label="狀態說明")
        el-table-column(prop="semester_label" label="學期標籤")
            template(#default='scope')
                SemesterLabelTag(:label="scope.row.semester_label")
        el-table-column(prop="init_consultation_date" label="初談入案時間" width="180px")
            template(#default='scope')
                div(v-if="form[scope.row.id]")
                    el-date-picker(v-model="form[scope.row.id].init_consultation_date" type="date" size="small" style="width: 80%;")
                .empty-cell(v-else) 無資料
        el-table-column(label="是否派案")
            template(#default='scope')
                el-tag(v-if="scope.row.status=='closed'" type="info" size="small") 已結案
                el-tag(v-else-if="scope.row.status=='assign'" size="small") 諮商中
                el-tag(v-else type="danger" size="small") 未派案
        el-table-column(prop="counselor_name" label="派案心理師")
            template(#default='scope')
                div(v-if="scope.row.status!='unassign'") {{scope.row.counselor_name}}
                .empty-cell(v-else) 無資料
        el-table-column(label="諮商時段")
            template(#default='scope')
                div(v-if="scope.row.status!='unassign'") {{scope.row.consultation_datetime}}
                .empty-cell(v-else) 無資料
        el-table-column(prop="first_consultation_date" label="第一次諮商日期" width="180px")
            template(#default='scope')
                div(v-if="scope.row.status!='unassign' && form[scope.row.id]")
                    el-date-picker(v-model="form[scope.row.id].first_consultation_date" type="date" size="small" style="width: 80%;")
                .empty-cell(v-else) 無資料
        el-table-column(prop="end_consultation_date" label="結案日期" width="90px")
            template(#default='scope')
                div(v-if="scope.row.status=='closed'") {{scope.row.end_consultation_date_text}}
                .empty-cell(v-else) 無資料
        el-table-column(label="諮商次數" width="60px")
            template(#default='scope')
                div(v-if="scope.row.status!='unassign'") {{scope.row.consultation_number}}
                .empty-cell(v-else) 無資料
        el-table-column(label="派案間隔時長(天)" width="80px")
            template(#default='scope')
                div(v-if="scope.row.status!='unassign'") {{scope.row.dispatch_interval_duration}}
                .empty-cell(v-else) 無資料
        el-table-column(label="功能按鈕" align="center" width="150px" fixed="right")
            template(v-slot:default="slotProps")
                .cell-actions
                    el-button(type="success" size="small"  @click="modifyCase(slotProps.row.id)") 修改
                    el-button(type="danger" size="small" @click="clickDelete(slotProps.row)") 刪除
</template>

<script>
import {weektimeMixin} from "@/components/weektimeMixin"
import { isEligible, EMPLOYMENT } from '@/utils/matchingRules'
import SemesterLabelTag from '@/components/SemesterLabelTag.vue';
import DataTable from '@/components/DataTable.vue';
import { downloadCSV as csvDownload } from '@/utils/exportTable'
import _ from "lodash"
export default {
    components: {SemesterLabelTag, DataTable},
    mixins: [weektimeMixin],
    data () {
        return {
            form: [],
            semester_label: '',
            labelOption: [],
            json_fields: {
                "姓名": "name",
                "學號": "caseId" ,
                "初談心理師": "init_counselor_name",
                "學期標籤": "semester_label",
                "初談後所提供可選擇的時段數目": "available_time_num",
                "危機程度": "crisis_level",
                "狀態說明": "discription",
                "初談入案時間": "init_consultation_date_text",
                "派案狀態": "status_text",
                "派案心理師": "counselor_name",
                "諮商時段": "consultation_datetime",
                "第一次諮商日期": "first_consultation_date_text",
                "結案諮商日期": "end_consultation_date_text",
                "諮商次數": "consultation_number",
                "派案間隔時長(天)": "dispatch_interval_duration"
            }
        }
    },
    async created() {
        await this.$store.dispatch('fetchSemesterLabel')
        this.labelOption = this.$store.state.semester_label.data
    },
    methods: {
        internDispatchable(row) {
            return isEligible(row, EMPLOYMENT.INTERN)
        },
        onSemesterChange() {
            if (this.$refs.table) this.$refs.table.reload(true)
        },
        // Enrich a raw case row with the display/text fields the table + export need.
        decorate(element) {
            const row = _.cloneDeep(element)
            if (element.init_consultation_date) {
                row.init_consultation_date_text = this.convertUTCtoStr(element.init_consultation_date)
            } else {
                row.init_consultation_date = '1970-1-1'
                row.init_consultation_date_text = 'N/A'
            }
            row.status_text = element.status == 'closed' ? '已結案' : (element.status == 'assign' ? '諮商中' : '未派案')
            row.first_consultation_date_text = 'N/A'
            row.consultation_datetime = 'N/A'
            row.consultation_number = 'N/A'
            row.dispatch_interval_duration = 'N/A'
            row.end_consultation_date_text = 'N/A'
            row.available_time_num = (element.available_time || '').split(',').filter(Boolean).length
            if (element.status == 'unassign') return row
            row.first_consultation_date_text = this.convertUTCtoStr(element.first_consultation_date)
            row.consultation_datetime = (element.consultation_day + element.consultation_time)
            row.consultation_number = this.countConsultationNumber(this.getDateStr(0), element.first_consultation_date)
            row.dispatch_interval_duration = this.countRangeDay(element.first_consultation_date, element.init_consultation_date)
            if (element.status == 'assign') return row
            row.end_consultation_date_text = this.convertUTCtoStr(element.end_consultation_date)
            return row
        },
        // Called by DataTable for one page.
        async fetchPage({ page, pageSize, q, sort, order }) {
            const params = { page, pageSize, q, sort, order }
            if (this.semester_label) params.semester_label = this.semester_label
            const res = await this.$http.get('/api/cases', { params })
            return {
                data: res.data.data.map(r => this.decorate(r)),
                meta: res.data.meta
            }
        },
        // Populate the per-row date-edit models for the current page's rows.
        onLoaded(rows) {
            const form = []
            rows.forEach(element => {
                form[element.id] = {
                    first_consultation_date: new Date(element.first_consultation_date),
                    init_consultation_date: new Date(element.init_consultation_date)
                }
            })
            this.form = form
        },
        // Export downloads the WHOLE table (all pages), not just the current one.
        async downloadCSV() {
            csvDownload(await this.loadAllForExport(), this.json_fields)
        },
        // Export every row of the CURRENT semester filter (all pages), not just
        // the visible page; no filter → the whole table.
        async loadAllForExport() {
            const params = {}
            if (this.semester_label) params.semester_label = this.semester_label
            const res = await this.$http.get('/api/cases', { params })
            return res.data.data.map(r => this.decorate(r))
        },
        getDateStr(date){
            var today
            if(date!=0)
                today = new Date(date)
            else
                today = new Date()
            return today.getFullYear()+'-'+(today.getMonth()+1)+'-'+today.getDate()
        },
        deleteCase(id) {
            this.$store.commit('SET_STATUS', 'pending')
            this.$http.delete("/api/cases/"+id)
            .then(() => {
                this.$message({
                    type: 'success',
                    message: '刪除成功!'
                });
                this.$refs.table.reload()
                this.$store.commit('SET_STATUS', 'end')
            })
            .catch((error) => {
                console.error(error)
            });
        },
        clickDelete(caseData) {
            this.$confirm('將永久刪除學號為 '+caseData.caseId+' 的資料, 是否繼續?', '提示', {
                confirmButtonText: '確定',
                cancelButtonText: '取消',
                type: 'warning'
                }).then(() => {
                    this.deleteCase(caseData.id)
                }).catch(() => {
                this.$message({
                    type: 'info',
                    message: '已取消刪除'
                })
            })
        },
        modifyCase(id) {
            this.$store.commit('SET_STATUS', 'pending')
            this.$http.put("/api/cases/"+id,{
                init_consultation_date: this.getDateStr(this.form[id].init_consultation_date),
                first_consultation_date: this.getDateStr(this.form[id].first_consultation_date)
            })
            .then(() => {
                this.$refs.table.reload()
                this.$store.commit('SET_STATUS', 'end')
            })
            .catch((error) => {
                console.error(error)
            });
        }
    }
}
</script>
